15	/// The kind of a folding range.
16	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
17	pub enum FoldingRangeKind {
18	    /// A comment block.
19	    Comment,
20	    /// An import block.
21	    Imports,
22	    /// A region (e.g., `# region` / `# endregion`).
23	    Region,
24	}
