26	/// A folding range in the source code.
27	#[derive(Debug, Clone, PartialEq, Eq)]
28	pub struct FoldingRange {
29	    /// The range to fold.
30	    pub range: TextRange,
31	    /// The kind of folding range.
32	    pub kind: Option<FoldingRangeKind>,
33	}
34	
35	impl FoldingRange {
36	    fn with_kind(self, kind: FoldingRangeKind) -> Self {
37	        Self {
38	            kind: Some(kind),
39	            ..self
40	        }
41	    }
42	}
43	
44	impl From<TextRange> for FoldingRange {
45	    fn from(range: TextRange) -> FoldingRange {
46	        FoldingRange { range, kind: None }
47	    }
48	}
