90	struct FoldingRangeVisitor<'a> {
91	    source: &'a str,
92	    ranges: Vec<FoldingRange>,
93	    tokens: &'a Tokens,
94	    range_filter: Option<TextRange>,
95	}
96	
97	impl FoldingRangeVisitor<'_> {
98	    fn intersects_range_filter(&self, range: TextRange) -> bool {
99	        self.range_filter
100	            .is_none_or(|range_filter| range_filter.intersect(range).is_some())
101	    }
102	
103	    fn contains_range_filter(&self, range: TextRange) -> bool {
104	        self.range_filter
105	            .is_none_or(|range_filter| range_filter.contains_range(range))
106	    }
107	
108	    /// Add the given folding range if it spans multiple lines.
109	    fn add_range(&mut self, folding_range: impl Into<FoldingRange>) {
110	        let folding_range = folding_range.into();
111	        if !self.contains_range_filter(folding_range.range) {
112	            return;
113	        }
114	        if !self.is_multiline(folding_range.range) {
115	            return;
116	        }
117	        self.ranges.push(folding_range);
118	    }
119	
120	    fn is_multiline(&self, range: TextRange) -> bool {
121	        self.source[range].contains('\n') || self.source[range].contains('\r')
122	    }
123	
124	    /// Compute folding ranges for consecutive import statements.
125	    /// Import blocks separated by blank lines are folded separately.
126	    ///
127	    /// TODO: It might be better to move this logic into the AST
128	    /// visitor via `enter_node`. I found it clearer to write it as
129	    /// a single separate pass over a sequence of statements. But if
130	    /// this ends up being a perf issue, it should be possible to
131	    /// do this within the existing AST pass.
132	    fn add_import_ranges(&mut self, stmts: &[Stmt]) {
133	        let mut import_range: Option<TextRange> = None;
134	        let mut prev_import_end: Option<TextSize> = None;
135	
136	        for stmt in stmts {
137	            if !self.intersects_range_filter(stmt.range()) {
138	                if let Some(range) = import_range {
139	                    self.add_range(FoldingRange::from(range).with_kind(FoldingRangeKind::Imports));
140	                }
141	                import_range = None;
142	                prev_import_end = None;
143	                continue;
144	            }
145	
146	            if matches!(stmt, Stmt::Import(_) | Stmt::ImportFrom(_)) {
147	                // Check if there's a blank line between this import and the previous one.
148	                let has_blank_line = prev_import_end
149	                    .is_some_and(|prev_end| self.has_blank_line_between(prev_end, stmt.start()));
150	
151	                if has_blank_line {
152	                    // Finalize the current import block and start a new one.
153	                    if let Some(range) = import_range {
154	                        self.add_range(
155	                            FoldingRange::from(range).with_kind(FoldingRangeKind::Imports),
156	                        );
157	                    }
158	                    import_range = Some(stmt.range());
159	                } else if let Some(ref mut range) = import_range {
160	                    *range = range.with_end(stmt.end());
161	                } else {
162	                    import_range = Some(stmt.range());
163	                }
164	                prev_import_end = Some(stmt.end());
165	            } else {
166	                if let Some(range) = import_range {
167	                    self.add_range(FoldingRange::from(range).with_kind(FoldingRangeKind::Imports));
168	                }
169	                import_range = None;
170	                prev_import_end = None;
171	            }
172	        }
173	        if let Some(range) = import_range {
174	            self.add_range(FoldingRange::from(range).with_kind(FoldingRangeKind::Imports));
175	        }
176	    }
177	
178	    /// Check if there's a blank line appearing anywhere between two positions.
179	    fn has_blank_line_between(&self, start: TextSize, end: TextSize) -> bool {
180	        let mut count = 0usize;
181	        for line in self.source[TextRange::new(start, end)].universal_newlines() {
182	            if !line.is_empty() {
183	                return count >= 2;
184	            }
185	            count += 1;
186	        }
187	        count >= 2
188	    }
